'use strict';
const commercialState={query:'',stage:'all',opportunityId:'',payload:null,lines:[],catalog:[]};
const phaseOneTabs=crmTabs;crmTabs=function(){const html=phaseOneTabs();return html.replace('</div>',`<button class="btn ${['pipeline','opportunity'].includes(crmState.tab)?'primary':''}" data-action="x-commerce-pipeline" aria-pressed="${['pipeline','opportunity'].includes(crmState.tab)}">Oportunidades</button></div>`);};
const commercialButton=(label,action,style='')=>button(label,'x-commerce-'+action,style).replace('<button ','<button type="button" ');
const stageLabel=s=>commercialState.payload?.stages?.[s]||s;
function opportunityCard(o){return `<article class="crm-deal"><small>${esc(o.number)} · ${esc(o.customer)}</small><h3>${esc(o.title)}</h3><strong>${money(o.amount)}</strong><p>${esc(o.nextAction||o.lostReason||'Venta vinculada')}</p><small>${o.nextDate?crmDate(o.nextDate):'Cerrada'} · ${esc(o.owner)}</small>${o.overdue?badge('Seguimiento vencido','warn'):''}${commercialButton('Abrir oportunidad','open-'+o.id,'text')}</article>`;}
function pipelineView(r){return `<div class="kpis crm-kpis">${kpi('Oportunidades abiertas',r.commercial.open,'Seguimiento comercial',true)+kpi('Valor estimado abierto',money(r.commercial.value),'No representa ventas ni dinero cobrado')+kpi('Ganadas',r.commercial.won,'Con venta o entrega vinculada')+kpi('Seguimientos vencidos',r.commercial.overdue,'Próximas acciones pendientes')}</div><section class="card"><div class="card-head"><div><h2>Una próxima acción para cada oportunidad.</h2><small>Abre la ficha de un cliente para crear una oportunidad.</small></div>${crmAction('Ver clientes','tab-customers','primary')}</div><form id="commercial-filter" class="crm-search"><label class="search">${icon('search')}<input name="query" value="${esc(commercialState.query)}" placeholder="Cliente, interés o número" aria-label="Buscar oportunidades"></label>${select('Etapa','stage',[['all','Todas las etapas'],...Object.entries(r.stages)],commercialState.stage)}${submit('Consultar')}</form></section>${commercialState.stage==='all'?`<p class="muted commercial-hint">Hasta 8 oportunidades por etapa. Usa el filtro de etapa para consultar el listado completo.</p><div class="commercial-board" aria-label="Tablero de oportunidades">${Object.entries(r.stages).map(([stage,label])=>`<section class="commercial-column"><header><h2>${esc(label)}</h2><span>${r.board[stage].total}</span></header>${r.board[stage].items.map(opportunityCard).join('')||'<p class="muted">Sin oportunidades.</p>'}${r.board[stage].total>8?commercialButton('Ver toda la etapa','stage-list-'+stage,'text'):''}</section>`).join('')}</div>`:`<section class="card crm-spacing">${r.opportunities.length?table(['Oportunidad / cliente','Valor estimado','Próxima acción',''],r.opportunities.map(o=>`<tr><td><strong>${esc(o.title)}</strong><small>${esc(o.number)} · ${esc(o.customer)}</small></td><td>${money(o.amount)}</td><td>${esc(o.nextAction||o.lostReason||'Cerrada')}<small>${o.nextDate?crmDate(o.nextDate):''}</small></td><td>${commercialButton('Abrir','open-'+o.id,'text')}</td></tr>`)):empty('Sin oportunidades en esta etapa.','Cambia el filtro o abre una oportunidad desde la ficha del cliente.')}</section>${crmPager(r.opportunityTotal)}`}`;}
function quoteStatus(q){return q.status==='draft'?'Borrador':q.expired?'Emitida · vencida':'Emitida';}
function opportunityView(r){const o=r.opportunity,latestIssued=Math.max(0,...o.quotes.filter(q=>q.status==='issued').map(q=>q.version)),closed=['won','lost'].includes(o.stage);return `<div class="row between crm-spacing">${commercialButton('Volver al tablero','pipeline','text')}<span class="crm-beta">${esc(o.number)}</span></div><div class="crm-detail-grid"><section class="card"><div class="card-head"><div><h2>${esc(o.title)}</h2><small>${esc(o.customer)} · ${esc(o.owner)}</small></div>${badge(r.stages[o.stage])}</div><div class="card-body"><dl class="crm-facts"><div><dt>Valor estimado</dt><dd>${money(o.amount)}</dd></div><div><dt>Próxima acción</dt><dd>${esc(o.nextAction||'Cerrada')}</dd></div><div><dt>Fecha</dt><dd>${o.nextDate?crmDate(o.nextDate):'—'}</dd></div></dl><p class="crm-text">${esc(o.description||'Sin notas adicionales.')}</p>${o.lostReason?`<p class="crm-text">Motivo de pérdida: ${esc(o.lostReason)}</p>`:''}<div class="row">${allowed('crm','editar')&&!closed&&!o.saleId?commercialButton('Editar oportunidad','edit','primary'):''}${allowed('crm','editar')&&o.stage!=='won'&&!o.saleId?commercialButton(o.stage==='lost'?'Reabrir oportunidad':'Cambiar etapa','stage'):''}${crmAction('Ficha del cliente','client-'+o.customerId,'text')}</div></div></section><section class="card card-body"><h2>De propuesta a venta.</h2><p class="crm-text">Una cotización no reserva mercancía ni mueve caja. Se revisan la vigencia, los precios y las existencias al continuar en el POS.</p>${o.saleId?`<div class="info-strip">Venta o separe vinculado: ${esc(o.saleId)}. ${o.stage==='won'?'Oportunidad ganada.':'Se cerrará como ganada al entregar el separe.'}</div>`:'<p class="muted">El cierre como ganada se realiza con la venta vinculada, sin duplicar registros.</p>'}</section></div><section class="card crm-spacing"><div class="card-head"><div><h2>Cotizaciones</h2><small>Las versiones emitidas conservan sus valores y condiciones.</small></div>${allowed('crm','crear')&&!closed&&!o.saleId?commercialButton(o.quotes.length?'Nueva versión':'Preparar cotización','quote-new','primary'):''}</div>${o.quotes.length?table(['Documento','Total','Vigencia','Estado',''],o.quotes.slice().reverse().map(q=>`<tr><td><strong>${esc(q.number)} · v${q.version}</strong><small>${crmDate(q.createdAt)}</small></td><td>${money(q.total)}</td><td>${crmDate(q.validUntil)}</td><td>${esc(quoteStatus(q))}</td><td>${commercialButton('Ver documento','quote-view-'+q.id,'text')}${q.status==='draft'&&allowed('crm','editar')&&!closed&&!o.saleId?commercialButton('Editar','quote-edit-'+q.id,'text')+commercialButton('Emitir','quote-issue-'+q.id,'text'):''}${q.status==='issued'&&q.version===latestIssued&&!q.expired&&!closed&&!o.saleId&&allowed('pos','crear')?commercialButton('Preparar venta','quote-pos-'+q.id,'text'):''}</td></tr>`)):empty('Prepara una propuesta con identidad Áurea.','Añade productos, cantidades, precios, vigencia y condiciones. No se reserva inventario.')}</section>`;}
const phaseOneLoad=loadCrm;loadCrm=async function(){if(!['pipeline','opportunity'].includes(crmState.tab)){const expectedTab=crmState.tab,expectedCustomer=crmState.customerId;await phaseOneLoad();if(expectedTab!==crmState.tab||expectedCustomer!==crmState.customerId)return;if(crmState.tab==='agenda'){const target=document.querySelector('#crm-content'),r=crmState.payload;if(target&&r?.followups?.length)target.insertAdjacentHTML('beforeend','<section class="card crm-spacing"><div class="card-head"><div><h2>Próximos pasos de oportunidades</h2><small>Se consultan desde la oportunidad, sin duplicarlos como tareas.</small></div></div>'+table(['Oportunidad / cliente','Próxima acción','Fecha',''],r.followups.map(o=>'<tr><td>'+esc(o.title)+'<small>'+esc(o.customer)+'</small></td><td>'+esc(o.nextAction)+'</td><td>'+crmDate(o.nextDate)+'</td><td>'+commercialButton('Abrir oportunidad','open-'+o.id,'text')+'</td></tr>'))+'</section>');}if(crmState.tab==='detail'&&crmState.payload?.detail){const c=crmState.payload.detail,target=document.querySelector('#crm-content');if(!target)return;const list=c.opportunities||[];target.insertAdjacentHTML('beforeend',`<section class="card crm-spacing"><div class="card-head"><h2>Oportunidades del cliente</h2>${allowed('crm','crear')?commercialButton('Nueva oportunidad','new','primary'):''}</div><div class="commercial-client-deals">${list.length?list.map(opportunityCard).join(''):empty('Un interés puede convertirse en una nueva historia.','Registra lo que busca el cliente y define el próximo paso.')}</div></section>`);}return;}const target=document.querySelector('#crm-content');if(!target)return;try{const q={page:crmState.page,stage:commercialState.stage,opportunityQuery:commercialState.query,...(crmState.tab==='opportunity'?{opportunityId:commercialState.opportunityId}:{})},r=await api('/api/crm?'+new URLSearchParams(q));if(!target.isConnected)return;commercialState.payload=r;crmState.payload=r;target.innerHTML=crmState.tab==='pipeline'?pipelineView(r):opportunityView(r);}catch(e){if(target.isConnected)target.innerHTML=empty('No pudimos consultar las oportunidades.',e.message,commercialButton('Reintentar','retry'));}};
function commercialOpportunityForm(edit=false){const o=edit?commercialState.payload.opportunity:null,cid=o?.customerId||crmState.payload.detail.id;modal(edit?'Editar oportunidad':'Una nueva oportunidad',pForm('commercial-opportunity-form',input('Interés del cliente','title',o?.title||'','text','required maxlength="160"')+input('Valor estimado COP','amount',o?.amount||0,'number','required min="0" step="1"')+select('Etapa','stage',Object.entries(commercialState.payload?.stages||crmState.payload.stages).filter(([id])=>!['won','lost'].includes(id)),o?.stage||'new')+input('Próxima acción','nextAction',o?.nextAction||'','text','required maxlength="180"')+input('Fecha de la próxima acción','nextDate',o?.nextDate||appState.today,'date','required')+`<label class="field"><span>Contexto de la oportunidad</span><textarea name="description" rows="3" maxlength="1000">${esc(o?.description||'')}</textarea></label>`,'Guardar oportunidad',`data-id="${esc(o?.id||'')}" data-customer="${esc(cid)}"`));}
function commercialStageForm(){const o=commercialState.payload.opportunity;modal('Actualizar etapa comercial',pForm('commercial-stage-form',select('Nueva etapa','stage',Object.entries(commercialState.payload.stages).filter(([id])=>id!=='won'),o.stage==='lost'?'contacted':o.stage)+input('Próxima acción (obligatoria si queda abierta)','nextAction',o.nextAction||'','text','maxlength="180"')+input('Fecha de próxima acción','nextDate',o.nextDate||appState.today,'date')+`<label class="field"><span>Motivo del cambio o de la pérdida</span><textarea name="reason" rows="3" maxlength="500" required></textarea></label><p class="muted">Las oportunidades ganadas se vinculan a una venta real.</p>`,'Guardar etapa',`data-id="${esc(o.id)}"`));}
function commercialQuote(id){return commercialState.payload.opportunity.quotes.find(q=>q.id===id);}
function quoteFormLines(){const target=document.querySelector('#commercial-quote-lines');if(!target)return;target.innerHTML=commercialState.lines.map((l,i)=>`<section class="commercial-quote-line"><div class="row between"><strong>${esc(l.name)}</strong>${commercialButton('Quitar','line-remove-'+i,'text')}</div><small>${esc(l.sku)} · ${l.measureType==='Pesaje'?'Gramos':'Unidades'} · ${l.stock===undefined?'Disponibilidad al vender':l.stock+' disponibles'}</small><div class="form-grid">${input(l.measureType==='Pesaje'?'Gramos':'Cantidad','lineQty'+i,l.qty,'number',`required min="${l.measureType==='Pesaje'?'0.000001':'1'}" step="${l.measureType==='Pesaje'?'0.000001':'1'}" data-commercial-line="${i}" data-field="qty"`)}${input('Precio COP / '+(l.measureType==='Pesaje'?'g':'un.'),'linePrice'+i,l.unitPrice,'number',`required min="0.000001" step="0.000001" data-commercial-line="${i}" data-field="unitPrice"`)}${input('Descuento COP','lineDiscount'+i,l.discount||0,'number',`required min="0" step="1" data-commercial-line="${i}" data-field="discount"`)}</div></section>`).join('')||'<p class="muted">Busca y añade productos para preparar la cotización.</p>';quotePreview();}
function quotePreview(){const el=document.querySelector('#commercial-quote-total');if(!el)return;const subtotal=commercialState.lines.reduce((n,l)=>n+Math.round(Number(l.qty)*Number(l.unitPrice))-Number(l.discount||0),0),tax=Math.round(subtotal*Number(data().settings.taxRate||0)/100);el.textContent='Subtotal: '+money(subtotal)+' · Impuesto: '+money(tax)+' · Total estimado: '+money(subtotal+tax);}
function commercialQuoteForm(id){const o=commercialState.payload.opportunity,q=id?commercialQuote(id):null,last=q||o.quotes.at(-1);commercialState.lines=(last?.lines||[]).map(l=>({...l}));const date=new Date(appState.today+'T12:00:00Z');date.setUTCDate(date.getUTCDate()+15);modal(q?'Editar borrador':'Preparar cotización',pForm('commercial-quote-form',`<p>${esc(o.title)} · ${esc(o.customer)}</p><div class="commercial-catalog-search"><label class="field"><span>Buscar producto por nombre o referencia</span><input class="input" id="commercial-product-query" type="search" placeholder="Ej. anillo o AN-018"></label>${commercialButton('Buscar productos','product-search')}</div><div id="commercial-product-results"></div><div id="commercial-quote-lines"></div>${input('Válida hasta','validUntil',q?.validUntil||date.toISOString().slice(0,10),'date','required')}<label class="field"><span>Condiciones de la propuesta</span><textarea name="terms" rows="3" maxlength="2000">${esc(last?.terms||'Disponibilidad sujeta a confirmación al vender. Esta cotización no reserva mercancía.')}</textarea></label><div class="info-strip" id="commercial-quote-total"></div><p class="muted">Se guardará un borrador. Emítelo después de revisar para conservar esta versión.</p>`,'Guardar borrador',`data-id="${esc(q?.id||'')}" data-opportunity="${esc(o.id)}"`));quoteFormLines();}
function quoteDocument(q){const logo=q.store.branding?.logo;return `<article class="commercial-quote-paper"><header><div>${logo?`<img src="${esc(logo)}" alt="Logo de la joyería">`:icon('diamond',30)}<strong>${esc(q.store.name||'Áurea')}</strong><small>${esc([q.store.legalName,q.store.taxId].filter(Boolean).join(' · '))}</small><small>${esc([q.store.address,q.store.phone].filter(Boolean).join(' · '))}</small></div><div><span class="crm-beta">${q.status==='draft'?'Borrador':'Cotización'}</span><h2>${esc(q.number)} · v${q.version}</h2><p>Válida hasta ${crmDate(q.validUntil)}</p></div></header><section><small>PREPARADA PARA</small><h3>${esc(q.customer.name)}</h3><p>${esc([q.customer.doc,q.customer.phone,q.customer.email].filter(Boolean).join(' · '))}</p></section>${table(['Pieza','Cantidad','Precio COP','Descuento COP','Total COP'],q.lines.map(l=>`<tr><td>${esc(l.name)}<small>${esc(l.sku)}</small></td><td>${l.qty} ${l.measureType==='Pesaje'?'g':'un.'}</td><td>${money(l.unitPrice)}</td><td>${money(l.discount)}</td><td>${money(l.lineTotal)}</td></tr>`))}<dl class="crm-facts"><div><dt>Subtotal</dt><dd>${money(q.subtotal)}</dd></div><div><dt>Impuesto (${q.taxRate} %)</dt><dd>${money(q.tax)}</dd></div><div><dt>Total de la propuesta</dt><dd><strong>${money(q.total)}</strong></dd></div></dl><p class="crm-text">${esc(q.terms)}</p><footer>Preparada en Áurea · Documento comercial, no es factura ni comprobante de pago. No reserva inventario.</footer></article>`;}
function showQuote(q){modal('Documento de cotización',quoteDocument(q),commercialButton('Imprimir / guardar PDF','quote-print'));document.querySelector('#dialog').classList.add('commercial-document-dialog');}
const commercialActions=extraUI.action;extraUI.action=async function(a,t){if(!a.startsWith('x-commerce-'))return commercialActions(a,t);const action=a.slice(11);if(action==='pipeline'){crmState.tab='pipeline';crmState.page=0;render();return;}if(action==='retry')return loadCrm();if(action.startsWith('stage-list-')){commercialState.stage=action.slice(11);crmState.page=0;render();return;}if(action.startsWith('open-')){commercialState.opportunityId=action.slice(5);crmState.tab='opportunity';render();return;}if(action==='new')return commercialOpportunityForm();if(action==='edit')return commercialOpportunityForm(true);if(action==='stage')return commercialStageForm();if(action==='quote-new')return commercialQuoteForm();if(action.startsWith('quote-edit-'))return commercialQuoteForm(action.slice(11));if(action.startsWith('quote-view-'))return showQuote(commercialQuote(action.slice(11)));if(action==='quote-print'){window.print();return;}if(action.startsWith('quote-issue-')){const q=commercialQuote(action.slice(12));return modal('Emitir cotización',pForm('commercial-issue-form',`<p><strong>${esc(q.number)} · versión ${q.version}</strong> por ${money(q.total)}.</p><p>Esta versión quedará conservada. Emitirla no envía mensajes al cliente ni reserva productos.</p>`,'Emitir versión revisada',`data-id="${esc(q.id)}"`));}if(action==='product-search'){const input=document.querySelector('#commercial-product-query'),target=document.querySelector('#commercial-product-results');const r=await api('/api/crm/catalog?'+new URLSearchParams({query:input.value}));if(!target.isConnected)return;commercialState.catalog=r.products;target.innerHTML=r.products.length?r.products.map((p,i)=>commercialButton(p.sku+' · '+p.name+' · '+money(p.price),'product-add-'+i,'text')).join(''):'<p class="muted">No encontramos productos activos.</p>';return;}if(action.startsWith('product-add-')){const p=commercialState.catalog[Number(action.slice(12))];if(commercialState.lines.some(l=>l.productId===p.id))return toast('Esta pieza ya está en la cotización. Ajusta su cantidad.');commercialState.lines.push({productId:p.id,name:p.name,sku:p.sku,measureType:p.measureType,weight:p.weight,stock:p.stock,qty:1,unitPrice:p.price,discount:0});document.querySelector('#commercial-product-results').innerHTML='';quoteFormLines();return;}if(action.startsWith('line-remove-')){commercialState.lines.splice(Number(action.slice(12)),1);quoteFormLines();return;}if(action.startsWith('quote-pos-')&&action!=='quote-pos-confirm')return reviewQuotePos(commercialQuote(action.slice(10)));if(action==='quote-pos-confirm')return transferQuoteToPos(commercialQuote(t.dataset.quote));if(action==='pos-detach'){clearCommercialPos();render();toast('Carrito desvinculado. La oportunidad sigue abierta.');return;}};
const commercialSubmit=extraUI.submit;extraUI.submit=async function(form,v){if(form.id==='commercial-filter'){commercialState.query=v.query;commercialState.stage=v.stage;crmState.page=0;render();return null;}if(form.id==='commercial-opportunity-form')return {command:'crm.opportunity.save',body:{...v,id:form.dataset.id||undefined,customerId:form.dataset.customer}};if(form.id==='commercial-stage-form')return {command:'crm.opportunity.stage',body:{...v,id:form.dataset.id}};if(form.id==='commercial-quote-form')return {command:'crm.quote.save',body:{id:form.dataset.id||undefined,opportunityId:form.dataset.opportunity,validUntil:v.validUntil,terms:v.terms,lines:commercialState.lines.map(l=>({productId:l.productId,qty:Number(l.qty),unitPrice:Number(l.unitPrice),discount:Number(l.discount||0)}))}};if(form.id==='commercial-issue-form')return {command:'crm.quote.issue',body:{id:form.dataset.id}};return commercialSubmit(form,v);};
document.addEventListener('input',e=>{if(e.target.dataset.commercialLine===undefined)return;const row=commercialState.lines[Number(e.target.dataset.commercialLine)];if(row){row[e.target.dataset.field]=Number(e.target.value);quotePreview();}});
document.querySelector('#dialog').addEventListener('close',()=>document.querySelector('#dialog').classList.remove('commercial-document-dialog'));
function clearCommercialPos(){appState.crmQuote=null;try{sessionStorage.removeItem('aurea-crm-pos-'+appState.user.id);}catch{}}
function reviewQuotePos(q){if(q.status!=='issued'||q.expired||q.saleId)throw Error('Selecciona una cotización emitida, vigente y sin venta.');modal('Preparar venta desde cotización',`<p><strong>${esc(q.number)} · v${q.version}</strong> · ${esc(q.customer.name)}</p><p>Total de la propuesta: ${money(q.total)}.</p><p class="muted">${appState.cart.length?'El carrito actual será reemplazado por esta propuesta. ':''}Podrás revisar el pago en el POS. Cargarla no registra una venta ni reserva productos.</p>`,`<button class="btn primary" data-action="x-commerce-quote-pos-confirm" data-quote="${esc(q.id)}">Cargar en el POS</button>`);}
async function transferQuoteToPos(q){await load();if(!allowed('pos','crear'))throw Error('Tu usuario no puede registrar ventas.');for(const l of q.lines){const p=data().products.find(p=>p.id===l.productId);if(!p?.active||p.stock<l.qty)throw Error('Revisa la disponibilidad de '+l.name+'.');if(p.price!==l.unitPrice&&!allowed('pos','editar')&&!allowed('inventario','editar'))throw Error('El precio cotizado requiere autorización de precio manual.');}if(Number(data().settings.taxRate||0)!==q.taxRate)throw Error('Cambió el impuesto. Prepara una nueva versión.');appState.cart=q.lines.map(l=>({productId:l.productId,qty:l.qty,unitPrice:l.unitPrice,discount:l.discount,manualPrice:data().products.find(p=>p.id===l.productId).price!==l.unitPrice}));appState.customerId=q.customerId;appState.crmQuote={id:q.id,number:q.number,version:q.version,userId:appState.user.id,customerId:q.customerId,opportunityId:q.opportunityId};try{sessionStorage.setItem('aurea-crm-pos-'+appState.user.id,JSON.stringify(appState.crmQuote));}catch{}closeModal();go('pos');}
const commercialLoad=load;load=async function(){await commercialLoad();if(appState.crmQuote?.userId!==appState.user.id)appState.crmQuote=null;try{if(!appState.crmQuote&&appState.cart.length){const draft=JSON.parse(sessionStorage.getItem('aurea-crm-pos-'+appState.user.id)||'null');if(draft?.userId===appState.user.id)appState.crmQuote=draft;}}catch{}};
const commercialMutate=mutate;mutate=async function(command,body,form){if(command==='sale.create'&&appState.crmQuote?.userId===appState.user.id)body={...body,crmQuoteId:appState.crmQuote.id};const r=await commercialMutate(command,body,form);if(command==='sale.create')clearCommercialPos();return r;};
const commercialDecorate=extraUI.decorate;extraUI.decorate=function(){commercialDecorate();if(appState.route==='pos'&&appState.crmQuote?.userId===appState.user.id){if(!appState.cart.length){clearCommercialPos();return;}document.querySelector('.page-heading').insertAdjacentHTML('afterend',`<div class="info-strip">${icon('receipt')}Venta preparada desde CRM · ${esc(appState.crmQuote.number)} · v${appState.crmQuote.version}. Los datos se validarán antes de registrar.${commercialButton('Desvincular cotización','pos-detach','text')}</div>`);}};
